<?php

declare(strict_types=1);

namespace SiteXPost\Modules\Research\Domain;

use Illuminate\Database\Eloquent\Concerns\HasUlids;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use Illuminate\Database\Eloquent\Relations\HasMany;
use Illuminate\Support\Carbon;
use SiteXPost\Kernel\Tenancy\BelongsToWorkspace;

/**
 * A keyword discovered for a campaign. Metrics live in keyword_metrics and
 * only come from a verified source (never generated by AI).
 *
 * @property string $id
 * @property string $workspace_id
 * @property string $campaign_id
 * @property ?string $cluster_id
 * @property string $keyword
 * @property string $normalized
 * @property string $fingerprint
 * @property string $language
 * @property string $country
 * @property string $intent
 * @property string $intent_source
 * @property ?string $topic_category
 * @property list<string>|null $sources
 * @property string $primary_source
 * @property array<string, mixed>|null $evidence
 * @property string $status
 * @property ?int $opportunity_score
 * @property array<string, mixed>|null $score_breakdown
 * @property array<string, mixed>|null $covered_by
 * @property ?string $last_seen_run_id
 * @property Carbon $first_seen_at
 * @property Carbon $data_collected_at
 * @property ?Carbon $created_at
 * @property ?Carbon $updated_at
 */
class Keyword extends Model
{
    use BelongsToWorkspace, HasUlids;

    protected $table = 'keywords';

    protected $guarded = ['*'];

    protected function casts(): array
    {
        return [
            'sources' => 'array',
            'evidence' => 'array',
            'score_breakdown' => 'array',
            'covered_by' => 'array',
            'opportunity_score' => 'integer',
            'first_seen_at' => 'datetime',
            'data_collected_at' => 'datetime',
        ];
    }

    /**
     * @return HasMany<KeywordMetric, $this>
     */
    public function metrics(): HasMany
    {
        return $this->hasMany(KeywordMetric::class);
    }

    /**
     * @return BelongsTo<TopicCluster, $this>
     */
    public function cluster(): BelongsTo
    {
        return $this->belongsTo(TopicCluster::class, 'cluster_id');
    }
}
